import React from "react";
import { Link } from "react-router-dom";
import styled, { keyframes, createGlobalStyle } from "styled-components";
import program1 from "../programs/program1";
import program2 from "../programs/program2";
import program3 from "../programs/program3";

const programs = [program1, program2, program3];

/* ---------- GLOBALS (system font, colors, selection) ---------- */
const Global = createGlobalStyle`
  :root{
    --bg: #0b0f14;          /* deep slate */
    --panel: rgba(255,255,255,0.04);
    --panelHover: rgba(255,255,255,0.07);
    --text: #e6eef8;
    --muted: #9aa7b5;
    --accent: #79f2ff;      /* neon cyan */
    --ring: rgba(121,242,255,0.35);
    --stroke: rgba(255,255,255,0.10);
  }

  *{ box-sizing: border-box; }
  html, body, #root{ height: 100%; }
  body{
    margin: 0;
    background: radial-gradient(1200px 700px at 20% 0%, #0f1620 0%, var(--bg) 60%)
                ,radial-gradient(1000px 600px at 100% 100%, #0c1219 0%, var(--bg) 55%);
    color: var(--text);
    font-family: 'SF Pro Display','Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  /* subtle grid overlay – hacker vibe */
  body::before{
    content:"";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background:
      linear-gradient(to bottom, rgba(255,255,255,0.035) 1px, transparent 1px) 0 0/100% 28px,
      linear-gradient(to right, rgba(255,255,255,0.035) 1px, transparent 1px) 0 0/28px 100%;
    mask-image: radial-gradient(1000px 600px at 50% -10%, black 15%, transparent 70%);
  }

  ::selection{
    background: rgba(121,242,255,0.25);
  }
`;

/* ---------- ANIMATIONS ---------- */
const rise = keyframes`
  from { opacity: 0; transform: translateY(6px) scale(.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
`;
const shimmer = keyframes`
  from { background-position: -200% 0; } to { background-position: 200% 0; }
`;

/* ---------- LAYOUT ---------- */
const Container = styled.div`
  max-width: 1120px;
  margin: 0 auto;
  padding: 72px 24px 56px;
`;

const Header = styled.header`
  text-align: center;
  margin-bottom: 48px;
  animation: ${rise} .6s ease both;

  .badge{
    display: inline-flex; gap: 8px; align-items: center;
    font-size: .82rem; letter-spacing: .08em; text-transform: uppercase;
    color: var(--muted);
    border: 1px solid var(--stroke); border-radius: 999px;
    padding: 6px 10px; backdrop-filter: blur(10px);
    background: var(--panel);
  }

  h1{
    margin: 14px 0 8px;
    font-size: clamp(2.2rem, 4vw, 3rem);
    font-weight: 800;
    letter-spacing: -0.02em;
    line-height: 1.05;
    background: linear-gradient(90deg, #cfe7ff 0%, var(--text) 40%, var(--accent) 110%);
    -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  }

  p{
    margin: 0 auto;
    max-width: 720px;
    color: var(--muted);
    font-size: 1rem;
  }
`;

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
`;

/* ---------- CARD ---------- */
const Card = styled(Link)`
  position: relative;
  border-radius: 16px;
  padding: 18px 18px 16px;
  text-decoration: none;
  color: var(--text);
  background: var(--panel);
  border: 1px solid var(--stroke);
  backdrop-filter: blur(12px);
  box-shadow: 0 6px 18px rgba(0,0,0,.25);
  transition: transform .18s ease, box-shadow .18s ease, background .18s ease, border-color .18s ease;
  animation: ${rise} .5s ease both;
  animation-delay: ${({ delay }) => delay || "0s"};

  &:hover{
    transform: translateY(-4px);
    background: var(--panelHover);
    border-color: var(--ring);
    box-shadow: 0 14px 28px rgba(0,0,0,.35), 0 0 0 4px var(--ring);
  }

  /* cyan accent line */
  &::after{
    content:"";
    position:absolute; left: 12px; right: 12px; bottom: 10px; height: 1.5px;
    background: linear-gradient(90deg, transparent, var(--accent), transparent);
    opacity: .55;
    transition: opacity .2s ease;
  }
  &:hover::after{ opacity: .95; }

  /* subtle animated sheen */
  &::before{
    content:"";
    position: absolute; inset: -1px;
    border-radius: 16px;
    pointer-events: none;
    background: linear-gradient(90deg,
      transparent, rgba(121,242,255,0.12), transparent);
    background-size: 200% 100%;
    opacity: 0; transition: opacity .25s;
  }
  &:hover::before{ opacity: 1; animation: ${shimmer} 1.4s linear infinite; }
`;

const Title = styled.div`
  font-weight: 700;
  font-size: 1.08rem;
  letter-spacing: -0.015em;
`;

const Meta = styled.div`
  display:flex; gap:10px; align-items:center; margin-top:8px;
  color: var(--muted); font-size: .85rem;

  .pill{
    border: 1px solid var(--stroke);
    border-radius: 999px;
    padding: 2px 8px;
    line-height: 1.6;
    background: rgba(255,255,255,0.03);
  }
`;

const Footer = styled.footer`
  margin-top: 48px;
  text-align: center;
  color: var(--muted);
  font-size: .9rem;

  a{
    color: var(--accent); text-decoration: none; font-weight: 600;
    position: relative;
  }
  a::after{
    content:""; position:absolute; left:0; bottom:-2px; height:2px; width:0%;
    background: var(--accent); transition: width .25s ease;
  }
  a:hover::after{ width:100%; }
`;

export default function Dashboard() {
  return (
    <>
      <Global />
      <Container>
        <Header>
          <div className="badge">JAVA • LAB</div>
          <h1>Minimal Java Programs</h1>
          <p>
            Surgical simplicity. Apple-grade polish with a hacker soul. Browse tiny,
            battle-tested Java snippets that compile clean and look even cleaner.
          </p>
        </Header>

        <Grid>
          {programs.map((p, idx) => (
            <Card key={p.id} to={`/program/${p.id}`} delay={`${idx * 0.04}s`} aria-label={`Open ${p.title}`}>
              <Title>{p.title}</Title>
              <Meta>
                <span className="pill">#{p.id}</span>
                <span className="pill">Java</span>
              </Meta>
            </Card>
          ))}
        </Grid>

        <Footer>
          built with care by{" "}
          <a href="https://www.instagram.com/_zainn.27" target="_blank" rel="noreferrer">
            @_zainn.27
          </a>
        </Footer>
      </Container>
    </>
  );
}
